SELECT OUT_TB.* FROM ( SELECT IN_TB.*, ROW_NUMBER() OVER (ORDER BY IN_TB.CUST_CD ) AS RNUM, (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'COMMON' AND Z.P_CODE = 'CD09' AND Z.CODE = IS_YN) AS IS_YN_NM FROM ( SELECT A.CUST_CD , A.CUST_NM , A.REPRESENT , A.BIZ_CONDITION , A.BIZ_TYPE , A.PUR_USE_YN , A.ADDR_DETAIL , A.CORP_REG_NO , A.BIZ_REG_NO, A.ZIP_NM, A.ZIP_CD, NVL2(B.ERP_CODE,'C001','C002') IS_YN FROM KYERP.TB_CM_CUSTOMER A, CRM_CUST_MGT B WHERE 1=1
AND UPPER(A.CUST_NM) LIKE UPPER('%'|| #{cust_nm} ||'%')
AND A.CUST_CD = B.ERP_CODE(+) AND A.PUR_USE_YN = 'N' AND A.TRANS_GBN ='00005' ) IN_TB WHERE 1=1
AND IN_TB.IS_YN = #{is_yn}
) OUT_TB WHERE RNUM BETWEEN #{startRow} AND #{endRow} ORDER BY RNUM DESC

SELECT COUNT(OUT_TB.CUST_CD) FROM( SELECT IN_TB.* FROM ( SELECT A.CUST_CD , A.CUST_NM , A.REPRESENT , A.BIZ_CONDITION , A.BIZ_TYPE , A.PUR_USE_YN , A.ADDR_DETAIL , A.CORP_REG_NO , A.BIZ_REG_NO, A.ZIP_NM, A.TRANS_GBN, NVL2(B.ERP_CODE, 'C001', 'C002') IS_YN FROM KYERP.TB_CM_CUSTOMER A, CRM_CUST_MGT B WHERE 1=1 AND A.CUST_CD = B.ERP_CODE(+) AND A.PUR_USE_YN = 'N' AND A.TRANS_GBN ='00005'
AND UPPER(A.CUST_NM) LIKE UPPER('%'|| #{cust_nm} ||'%')
)IN_TB WHERE 1=1
AND IN_TB.IS_YN = #{is_yn}
)OUT_TB


