mapper.update:

MERGE INTO 
    CRM_CUST_INSTALL_HIST
USING DUAL 
    ON (SEQ = #{seq}  AND DTL_SEQ = #{dtl_seq})
    WHEN MATCHED THEN     
        UPDATE SET
		    ERP_CODE = #{erp_code}
		    ,GROUP_CODE1 = #{group_code1}
		    ,GROUP_CODE2 = #{group_code2}
		    ,GROUP_CODE3 = #{group_code3}
		    ,ITEM_NM = #{item_nm}
		    ,REG_DATE = sysdate
		    ,REG_ID = #{reg_id}
		    ,ETC = #{etc}
		    ,SERIAL_NO = #{serial_no}
    WHEN NOT MATCHED THEN
        INSERT (
	        SEQ
			,DTL_SEQ
			,ERP_CODE
			,GROUP_CODE1
			,GROUP_CODE2
			,GROUP_CODE3
			,ITEM_NM
			,REG_DATE
			,REG_ID
			,ETC
			,SERIAL_NO
		)
        VALUES(
			#{seq}
			,#{dtl_seq}
			,#{erp_code}
			,#{group_code1}
			,#{group_code2}
			,#{group_code3}
			,#{item_nm}
			,sysdate
			,#{reg_id}
			,#{etc}
			,#{serial_no}
        )

mapper.delete:
DELETE CRM_CUST_INSTALL_HIST
WHERE SEQ = #{seq}  
	AND DTL_SEQ = #{dtl_seq}

